export interface UnlockStopInput {
  /** The station to open. The server resolves its language from the row itself and mints the ledger refId as stop:<language>:<groupId>, so no client-supplied idempotency key is accepted here. */
  lessonGroupId: number;
}

export interface StopUnlockResult {
  balance: number;
  lessonGroupId: number;
  languageCode: string;
  unlocked: boolean;
  /** False when the learner already owned this stop — the call is a no-op that deducts nothing. Clients must not re-render a "spent" animation for it. */
  charged: boolean;
  cost: number;
}

/**
 * Whether the learner has a streak break worth mending, and what mending it would cost. `eligible` false means there is nothing to offer — no break, an absence too long to be a slip, or a break older than the repair window — and clients must show nothing at all in that case.
 */
export interface StreakRepairOffer {
  eligible: boolean;
  /** The YYYY-MM-DD local day that broke the streak. */
  missedDay: string | null;
  /** The streak the learner would have again once the day is covered, measured on the same ladder the progress summary climbs. */
  restoresStreakDays: number;
  cost: number;
  balance: number;
}

export interface StreakRepairResult {
  balance: number;
  repairedDay: string;
  restoredStreakDays: number;
  /** False when this day was already repaired — the call is a no-op that deducts nothing. */
  charged: boolean;
  cost: number;
}

export interface TokenSpendResult {
  balance: number;
  granted: string;
  stationPausesEquipped: number;
  expressMultiplierActiveUntil?: string | null;
}

/**
 * One learner on the caller's blocked list. Carries the PUBLIC name only, never the private display name: everybody on this list is by definition not a friend any more, so the rule that governs the global feed and board governs this payload too.
 */
export interface BlockedUser {
  userId: string;
  /** The name to render, which is the username if they chose one and the same stable pseudonym the feed showed otherwise, so the row the learner blocked is the row they recognise here. */
  displayName: string;
  /** The learner's public name, or null if they never set one. */
  username?: string | null;
  /** When the block was made. */
  createdAt: string;
}

/**
 * The learner a feed entry is about. Name and mascot only: a feed never carries an email address, because a friend code is deliberately the only way to find another learner.
 */
export interface FeedActor {
  userId: string;
  /** The name to render. On `scope=friends` it is the learner's private display name; on `scope=all` it carries the USERNAME instead, and the private display name is never sent. */
  displayName: string | null;
  /** The learner's public name, or null if they never set one. */
  username?: string | null;
  /** The outfit this friend's Bolo is wearing (see OutfitCatalog ids), or null for the canonical undressed bird. */
  equippedOutfit: string | null;
  /** The head accessory this friend's Bolo is wearing, or null. A separate slot from the garment. */
  equippedAccessory: string | null;
  /** Whether this friend's First Class window is open right now. A boolean, never the expiry timestamp. */
  firstClassActive: boolean;
}

/**
 * Everything a renderer needs beyond the type and the ref.
 */
export type FeedEntryPayload = { [key: string]: unknown } | null;

/**
 * One moment from the activity feed. Some come from the activity_events log; the rest are PROJECTED from what learners actually do often (practice_day, stop_completed, game_played), because the log alone holds only milestones and a feed of milestones is nearly empty.
 */
export interface FeedEntry {
  /** Stable across reads and prefixed by source ("e", "p", "s", "g"), because a projection has no single sequence to borrow from and two sources would otherwise collide on 1. Use it as a key, not as a row id in any table. */
  id: string;
  /** What happened: `equip_outfit`, `equip_accessory`, `badge_earned` or `zone_closeout`. Left open rather than enumerated so an older client meeting a newer event type can skip it instead of failing to parse the page; clients render nothing for a type they do not know. */
  type: string;
  /** The subject of the event: the item id for an equip, the badge key for a badge, `languageCode:categoryId` for a zone closeout. */
  refId: string;
  /** Everything a renderer needs beyond the type and the ref. */
  payload: FeedEntryPayload;
  createdAt: string;
  actor: FeedActor;
}

/**
 * One learner's standing on the leaderboard.
 */
export interface LeaderboardEntry {
  userId: string;
  /** The name to render for this row. On `scope=friends` it is the learner's private display name, which is right because friends know each other. On `scope=all` it carries the USERNAME instead, and the private display name is never sent. */
  displayName: string | null;
  /** The learner's public name, or null if they have never set one. A row on the global board always has one, by construction. */
  username?: string | null;
  /** XP summed across every language from the XP ledger, over the requested window. All-time includes the pre-ledger backfill; the weekly window excludes it. */
  xp: number;
  /** This learner's current streak in days, read the same way every other streak surface reads it (their own time zone, covers included). Also the first tie-break when two learners are level on XP. */
  currentStreakDays: number;
  /** When this learner last earned XP in the window, which is when they reached the total shown. The final tie-break: level on XP and level on streak, whoever got there first ranks higher. Null for a learner with no XP in the window. */
  reachedAt: string | null;
  /** 1-based rank, highest XP first. */
  rank: number;
  /** True for the caller's own entry. */
  isSelf: boolean;
  /** The outfit this learner's Bolo is wearing (see OutfitCatalog ids), or null for the canonical undressed bird. Carried on the row so friend and leaderboard lists render each learner's mascot without a per-row fetch. Optional: older clients that predate outfits on rows simply ignore it. */
  equippedOutfit?: string | null;
  /** The head accessory this learner's Bolo is wearing, or null. A garment and an accessory are separate slots, so a row that shipped only the garment would show a pagdi-wearing friend bare-headed. */
  equippedAccessory?: string | null;
  /** Whether this learner's First Class window is open right now, resolved server-side from the expiry the spend wrote. A boolean and never the timestamp: a friend's exact expiry is not the reader's business, and a countdown on someone else's row is noise. */
  firstClassActive: boolean;
}

